document.addEventListener('DOMContentLoaded', function () {
  const target = document.querySelector('.feature-grid');
  const outroBloco = document.querySelector('.elementor-element-864f9c0');
  const footer = document.querySelector('#footer-change-color');

  if (!target || !footer) return;

  // ===== Opção A: considerar que "já rolou" se a página abriu fora do topo
  let hasScrolledOnce = window.scrollY > 0;
  let lastScrollY = window.scrollY;

  window.addEventListener('scroll', () => {
    hasScrolledOnce = true;
  });

  // ===== Opção C: funções para aplicar/limpar estado e checar visibilidade inicial
  function isVisible(el, threshold = 0.5) {
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const vh = window.innerHeight || document.documentElement.clientHeight;
    const visibleH = Math.min(r.bottom, vh) - Math.max(r.top, 0);
    return visibleH > 0 && (visibleH / r.height) >= threshold;
  }

  function applyLight() {
    document.body.style.backgroundColor = '#F5F5F5';

    if (outroBloco) {
      outroBloco.style.backgroundColor = '#F5F5F5';
      outroBloco.style.transition = 'background-color 0.5s ease';
    }

    document.querySelectorAll('.change_color_dark').forEach(el => {
      el.style.color = '#4B5A68';
      el.style.transition = 'color 0.5s ease, background-color 0.5s ease';
    });

    document.querySelectorAll('.change_color_white').forEach(el => {
      el.style.color = '#F5F5F5';
      el.style.backgroundColor = '#F5F5F5';
      el.style.transition = 'color 0.5s ease, background-color 0.5s ease';
    });
  }

  function clearLight() {
    document.body.style.backgroundColor = '';

    if (outroBloco) {
      outroBloco.style.backgroundColor = '';
    }

    document.querySelectorAll('.change_color_dark').forEach(el => {
      el.style.color = '';
    });

    document.querySelectorAll('.change_color_white').forEach(el => {
      el.style.color = '';
      el.style.backgroundColor = '';
    });
  }

  // ===== Estado inicial (aplicado no load, antes do observer reagir)
  (function applyInitialState() {
    const targetVisible = isVisible(target, 0.5);
    const footerVisible = isVisible(footer, 0.5);

    if (footerVisible) {
      clearLight();
    } else if (targetVisible || window.scrollY > target.offsetTop) {
      // Mantém claro também quando a página carrega abaixo do target
      applyLight();
    } else {
      clearLight();
    }
  })();

  // ===== Observer para manter o comportamento dinâmico original
  const observer = new IntersectionObserver(
    function (entries) {
      if (!hasScrolledOnce) return; // mantém o freio contra "flash" no topo

      entries.forEach(entry => {
        const currentScrollY = window.scrollY;
        const scrollingDown = currentScrollY > lastScrollY;
        lastScrollY = currentScrollY;

        if (entry.target === target) {
          if (entry.isIntersecting) {
            applyLight();
          } else {
            if (!scrollingDown) {
              clearLight();
            }
          }
        }

        if (entry.target === footer) {
          if (entry.isIntersecting) {
            clearLight();
          } else {
            if (!scrollingDown && hasScrolledOnce) {
              applyLight();
            }
          }
        }
      });
    },
    { threshold: 0.5 }
  );

  observer.observe(target);
  observer.observe(footer);
});
